window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["world-models"]={"title":"世界模型：在内部状态中预测行动后的世界","subtitle":"从状态表示、转移与奖励模型，到想象滚动、模型预测控制、不确定性和模型利用，理解“在脑中试走”怎样帮助又怎样误导智能体。","thesis":"世界模型学习的是环境在动作下怎样变化的<b>近似动力学</b>，智能体可在模型内低成本比较候选行动；但规划器会主动寻找预测误差并沿长轨迹放大，因此价值不只取决于单步重建，还取决于状态充分性、不确定性与真实环境闭环校正。","quality":{"contractVersion":2,"formulas":[{"id":"world-models-formula-1","section":2,"formulaIndex":1,"symbols":[{"name":"z","meaning":"公式中的“z”是本节计算所使用的量，具体角色由紧邻文字定义。","evidence":"2 状态、动作、转移和奖励 机制 一个可规划世界模型至少要回答哪几个量"}]}],"examples":[{"section":4,"evidence":{"setup":"4 一次两步规划怎样在模型内发生 运行示例 小车距目标 3 格、前方第 2 格有坑时","rule":"短视奖励和两步滚动会选出什么","steps":"距目标 3 坑位未知/估计 直行 a₁ r̂₁=+2","interpretation":"距目标 2 第二步预测落坑 r̂₂=−10 绕行 a₂ r̂₁=0"}}],"termReviews":[],"sectionContracts":[{"section":1,"definition":{"answer":"本节对“世界模型解决什么问题”的界定是：1 世界模型解决什么问题 直觉 如果每个候选行动都要在真实世界试一次","evidence":"1 世界模型解决什么问题 直觉 如果每个候选行动都要在真实世界试一次"},"problem":{"answer":"本节处理的实际问题是：为什么规划既昂贵又危险","evidence":"为什么规划既昂贵又危险"},"inputOutput":{"answer":"本节的输入与输出关系是：真实机器人碰撞、游戏失败或生产系统写操作都有成本","evidence":"真实机器人碰撞、游戏失败或生产系统写操作都有成本"},"mechanism":{"answer":"本节给出的工作机制是：世界模型把观察压成内部状态","evidence":"世界模型把观察压成内部状态"},"interpretation":{"answer":"本节要求这样解释结果：预测采取动作后的下一状态、奖励或终止概率","evidence":"预测采取动作后的下一状态、奖励或终止概率"},"boundary":{"answer":"本节明确的适用边界是：使智能体能在“想象”中筛掉明显差方案","evidence":"使智能体能在“想象”中筛掉明显差方案"}},{"section":2,"definition":{"answer":"本节对“状态、动作、转移和奖励”的界定是：2 状态、动作、转移和奖励 机制 一个可规划世界模型至少要回答哪几个量","evidence":"2 状态、动作、转移和奖励 机制 一个可规划世界模型至少要回答哪几个量"},"problem":{"answer":"本节处理的实际问题是：z t = E ( o ≤ t ), hat z t + 1 = f ( z t , a t ), hat r t = g ( z t , a t ) 编码器 E 把当前及历史观察变成状态 z","evidence":"z t = E ( o ≤ t ), hat z t + 1 = f ( z t , a t ), hat r t = g ( z t , a t ) 编码器 E 把当前及历史观察变成状态 z"},"inputOutput":{"answer":"本节的输入与输出关系是：动力学 f 预测动作后的状态","evidence":"动力学 f 预测动作后的状态"},"mechanism":{"answer":"本节给出的工作机制是：可选解码器把状态还原成观察用于辅助训练","evidence":"可选解码器把状态还原成观察用于辅助训练"},"interpretation":{"answer":"本节要求这样解释结果：奖励模型 g 估计任务价值","evidence":"奖励模型 g 估计任务价值"},"boundary":{"answer":"本节明确的适用边界是：若环境部分可观察","evidence":"若环境部分可观察"}},{"section":3,"definition":{"answer":"本节对“训练信号从哪里来”的界定是：3 训练信号从哪里来 学习 模型怎样从真实轨迹学会“如果这样做会怎样”","evidence":"3 训练信号从哪里来 学习 模型怎样从真实轨迹学会“如果这样做会怎样”"},"problem":{"answer":"本节处理的实际问题是：收集轨迹 (o,a,r,o′)","evidence":"收集轨迹 (o,a,r,o′)"},"inputOutput":{"answer":"本节的输入与输出关系是：同时优化表示、下一状态/观察、奖励和终止预测","evidence":"同时优化表示、下一状态/观察、奖励和终止预测"},"mechanism":{"answer":"本节给出的工作机制是：实践中会组合重建、对比、潜在一致性和任务损失","evidence":"实践中会组合重建、对比、潜在一致性和任务损失"},"interpretation":{"answer":"本节要求这样解释结果：只预测奖励又可能丢失对未来行动重要但当前无奖励的因素","evidence":"只预测奖励又可能丢失对未来行动重要但当前无奖励的因素"},"boundary":{"answer":"本节明确的适用边界是：只重建像素容易把容量花在背景纹理","evidence":"只重建像素容易把容量花在背景纹理"}},{"section":4,"definition":{"answer":"本节对“一次两步规划怎样在模型内发生”的界定是：4 一次两步规划怎样在模型内发生 运行示例 小车距目标 3 格、前方第 2 格有坑时","evidence":"4 一次两步规划怎样在模型内发生 运行示例 小车距目标 3 格、前方第 2 格有坑时"},"problem":{"answer":"本节处理的实际问题是：再滚动规划 图 1 两步想象使规划器看到短期正奖励后的灾难","evidence":"再滚动规划 图 1 两步想象使规划器看到短期正奖励后的灾难"},"inputOutput":{"answer":"本节的输入与输出关系是：短视奖励和两步滚动会选出什么","evidence":"短视奖励和两步滚动会选出什么"},"mechanism":{"answer":"本节给出的工作机制是：距目标 3 坑位未知/估计 直行 a₁ r̂₁=+2","evidence":"距目标 3 坑位未知/估计 直行 a₁ r̂₁=+2"},"interpretation":{"answer":"本节要求这样解释结果：距目标 2 第二步预测落坑 r̂₂=−10 绕行 a₂ r̂₁=0","evidence":"距目标 2 第二步预测落坑 r̂₂=−10 绕行 a₂ r̂₁=0"},"boundary":{"answer":"本节明确的适用边界是：距目标仍 3 第二步安全前进 r̂₂=+2 Ĝ直行 2+0.9×(−10)=−7 Ĝ绕行 0+0.9×2=1.8 执行绕行 再观察现实 真实观察校正模型状态","evidence":"距目标仍 3 第二步安全前进 r̂₂=+2 Ĝ直行 2+0.9×(−10)=−7 Ĝ绕行 0+0.9×2=1.8 执行绕行 再观察现实 真实观察校正模型状态"}},{"section":5,"definition":{"answer":"本节对“模型预测控制为什么只执行第一步”的界定是：5 模型预测控制为什么只执行第一步 闭环 既然已经规划出十步","evidence":"5 模型预测控制为什么只执行第一步 闭环 既然已经规划出十步"},"problem":{"answer":"本节处理的实际问题是：为什么不一次全部执行","evidence":"为什么不一次全部执行"},"inputOutput":{"answer":"本节的输入与输出关系是：模型预测控制每轮在模型内滚动 H 步","evidence":"模型预测控制每轮在模型内滚动 H 步"},"mechanism":{"answer":"本节给出的工作机制是：收到真实观察后更新状态并重新优化","evidence":"收到真实观察后更新状态并重新优化"},"interpretation":{"answer":"本节要求这样解释结果：它用频繁校正限制预测误差累积","evidence":"它用频繁校正限制预测误差累积"},"boundary":{"answer":"本节明确的适用边界是：却只执行第一个动作","evidence":"却只执行第一个动作"}},{"section":6,"definition":{"answer":"本节对“误差为什么随滚动长度放大”的界定是：6 误差为什么随滚动长度放大 误差传播 单步平均只错一点","evidence":"6 误差为什么随滚动长度放大 误差传播 单步平均只错一点"},"problem":{"answer":"本节处理的实际问题是：为什么长规划仍会完全偏离","evidence":"为什么长规划仍会完全偏离"},"inputOutput":{"answer":"本节的输入与输出关系是：若每步状态误差上界为 ε","evidence":"若每步状态误差上界为 ε"},"mechanism":{"answer":"本节给出的工作机制是：动力学对状态的敏感度近似 L","evidence":"动力学对状态的敏感度近似 L"},"interpretation":{"answer":"本节要求这样解释结果：则粗略误差递推为 eₜ₊₁≤L·eₜ+ε","evidence":"则粗略误差递推为 eₜ₊₁≤L·eₜ+ε"},"boundary":{"answer":"本节明确的适用边界是：L<1 时误差可能受控","evidence":"L<1 时误差可能受控"}},{"section":7,"definition":{"answer":"本节对“状态混叠和不确定性”的界定是：若单帧看不出小车向左还是向右运动","evidence":"若单帧看不出小车向左还是向右运动"},"problem":{"answer":"本节处理的实际问题是：却需要相反动作时","evidence":"却需要相反动作时"},"inputOutput":{"answer":"本节的输入与输出关系是：7 状态混叠和不确定性 失败边界 两个画面看起来相同","evidence":"7 状态混叠和不确定性 失败边界 两个画面看起来相同"},"mechanism":{"answer":"本节给出的工作机制是：编码成相同 z 就是状态混叠","evidence":"编码成相同 z 就是状态混叠"},"interpretation":{"answer":"本节要求这样解释结果：确定性均值预测可能得到现实中不存在的中间结果","evidence":"确定性均值预测可能得到现实中不存在的中间结果"},"boundary":{"answer":"本节明确的适用边界是：同一状态/动作会对应两种未来","evidence":"同一状态/动作会对应两种未来"}},{"section":8,"definition":{"answer":"本节对“怎样发现模型利用”的界定是：8 怎样发现模型利用 评测 规划器在模型里获得超高回报","evidence":"8 怎样发现模型利用 评测 规划器在模型里获得超高回报"},"problem":{"answer":"本节处理的实际问题是：为什么真实环境反而变差","evidence":"为什么真实环境反而变差"},"inputOutput":{"answer":"本节的输入与输出关系是：策略找到模型漏洞","evidence":"策略找到模型漏洞"},"mechanism":{"answer":"本节给出的工作机制是：例如预测某个不现实动作会反复得分","evidence":"例如预测某个不现实动作会反复得分"},"interpretation":{"answer":"本节要求这样解释结果：比较模型预测回报与真实回放回报","evidence":"比较模型预测回报与真实回放回报"},"boundary":{"answer":"本节明确的适用边界是：差值称为 model exploitation gap","evidence":"差值称为 model exploitation gap"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>定义状态/转移/奖励模型；计算多步误差和回报；解释模型预测控制；识别状态混叠与模型利用。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>世界模型解决什么问题<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">如果每个候选行动都要在真实世界试一次，为什么规划既昂贵又危险？</p><p>真实机器人碰撞、游戏失败或生产系统写操作都有成本。世界模型把观察压成内部状态，预测采取动作后的下一状态、奖励或终止概率，使智能体能在“想象”中筛掉明显差方案，再只执行一个候选。它不是世界的完整复制，而是针对决策保留必要变量的近似模拟器。</p><div class=\"dd-note\"><b>关键边界：</b>生成一段逼真视频不等于预测了行动后果；像素看起来合理，却可能在碰撞、库存或奖励上完全错误。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>状态、动作、转移和奖励<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">一个可规划世界模型至少要回答哪几个量？</p><div class=\"dd-formula\" data-formula-id=\"world-models-formula-1\" data-display=\"mathml\"><math display=\"block\" aria-label=\"z t =E(o ≤t ), hat z t+1 =f(z t ,a t ), hat r t =g(z t ,a t )\"><mrow><mi>z</mi><mspace width=\"0.35em\"/><mi>t</mi><mspace width=\"0.35em\"/><mo>=</mo><mi>E</mi><mo>(</mo><mi>o</mi><mspace width=\"0.35em\"/><mo>≤</mo><mi>t</mi><mspace width=\"0.35em\"/><mo>),</mo><mspace width=\"0.35em\"/><mi>hat</mi><mspace width=\"0.35em\"/><mi>z</mi><mspace width=\"0.35em\"/><mi>t</mi><mo>+</mo><mn>1</mn><mspace width=\"0.35em\"/><mo>=</mo><mi>f</mi><mo>(</mo><mi>z</mi><mspace width=\"0.35em\"/><mi>t</mi><mspace width=\"0.35em\"/><mo>,</mo><mi>a</mi><mspace width=\"0.35em\"/><mi>t</mi><mspace width=\"0.35em\"/><mo>),</mo><mspace width=\"0.35em\"/><mi>hat</mi><mspace width=\"0.35em\"/><mi>r</mi><mspace width=\"0.35em\"/><mi>t</mi><mspace width=\"0.35em\"/><mo>=</mo><mi>g</mi><mo>(</mo><mi>z</mi><mspace width=\"0.35em\"/><mi>t</mi><mspace width=\"0.35em\"/><mo>,</mo><mi>a</mi><mspace width=\"0.35em\"/><mi>t</mi><mspace width=\"0.35em\"/><mo>)</mo></mrow></math></div><p>编码器 E 把当前及历史观察变成状态 z；动力学 f 预测动作后的状态；奖励模型 g 估计任务价值；可选解码器把状态还原成观察用于辅助训练。若环境部分可观察，单帧不足以区分速度或隐藏库存，状态必须整合历史或显式信念分布。</p><p>“状态充分”指：给定 z 和动作后，预测未来不再需要更早历史。它是建模目标，不会因向量维度足够大自动成立。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>训练信号从哪里来<span class=\"dd-badge eng\">学习</span></h2><p class=\"dd-lead\">模型怎样从真实轨迹学会“如果这样做会怎样”？</p><p>收集轨迹 (o,a,r,o′)，同时优化表示、下一状态/观察、奖励和终止预测。只重建像素容易把容量花在背景纹理；只预测奖励又可能丢失对未来行动重要但当前无奖励的因素。实践中会组合重建、对比、潜在一致性和任务损失，并保持探索数据覆盖规划器可能选择的动作。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>目标</th><th>保留什么</th><th>盲区</th></tr></thead><tbody><tr><td>观察重建</td><td>视觉细节</td><td>漂亮但与控制无关</td></tr><tr><td>潜在转移</td><td>状态动力学</td><td>表示坍塌需额外约束</td></tr><tr><td>奖励/终止</td><td>任务直接信号</td><td>稀疏奖励、代理漏洞</td></tr><tr><td>对比预测</td><td>可区分未来</td><td>负样本与增强定义偏差</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>一次两步规划怎样在模型内发生<span class=\"dd-badge math\">运行示例</span></h2><p class=\"dd-lead\">小车距目标 3 格、前方第 2 格有坑时，短视奖励和两步滚动会选出什么？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 680 250\" role=\"img\" aria-label=\"世界模型对直行和绕行两条两步轨迹进行想象并比较预测回报\"><defs><marker id=\"wm1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"22\" y=\"92\" width=\"112\" height=\"60\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"78\" y=\"116\" text-anchor=\"middle\" class=\"svg-t\">z₀：距目标 3</text><text x=\"78\" y=\"136\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">坑位未知/估计</text><path d=\"M134,111 L190,62\" stroke=\"#6b7484\" marker-end=\"url(#wm1)\"/><path d=\"M134,133 L190,184\" stroke=\"#6b7484\" marker-end=\"url(#wm1)\"/><rect x=\"192\" y=\"28\" width=\"142\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"263\" y=\"52\" text-anchor=\"middle\" class=\"svg-t\">直行 a₁</text><text x=\"263\" y=\"72\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">r̂₁=+2，距目标 2</text><text x=\"263\" y=\"88\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">第二步预测落坑 r̂₂=−10</text><rect x=\"192\" y=\"160\" width=\"142\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"263\" y=\"184\" text-anchor=\"middle\" class=\"svg-t\">绕行 a₂</text><text x=\"263\" y=\"204\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">r̂₁=0，距目标仍 3</text><text x=\"263\" y=\"220\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">第二步安全前进 r̂₂=+2</text><path d=\"M334,63 L412,63\" stroke=\"#6b7484\" marker-end=\"url(#wm1)\"/><path d=\"M334,195 L412,195\" stroke=\"#6b7484\" marker-end=\"url(#wm1)\"/><rect x=\"414\" y=\"30\" width=\"118\" height=\"66\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"473\" y=\"54\" text-anchor=\"middle\" class=\"svg-t\">Ĝ直行</text><text x=\"473\" y=\"77\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">2+0.9×(−10)=−7</text><rect x=\"414\" y=\"162\" width=\"118\" height=\"66\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"473\" y=\"186\" text-anchor=\"middle\" class=\"svg-t\">Ĝ绕行</text><text x=\"473\" y=\"209\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">0+0.9×2=1.8</text><path d=\"M532,195 L576,195\" stroke=\"#6b7484\" marker-end=\"url(#wm1)\"/><rect x=\"578\" y=\"166\" width=\"84\" height=\"58\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"620\" y=\"190\" text-anchor=\"middle\" class=\"svg-t\">执行绕行</text><text x=\"620\" y=\"209\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">再观察现实</text><path d=\"M620,165 C614,118 475,116 473,98\" fill=\"none\" stroke=\"#6b7484\" stroke-dasharray=\"4 3\" marker-end=\"url(#wm1)\"/><text x=\"552\" y=\"119\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">真实观察校正模型状态，再滚动规划</text></svg><figcaption>图 1　两步想象使规划器看到短期正奖励后的灾难；只执行第一步并重新观察，是模型预测控制降低长滚动误差的核心。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>候选</th><th>r̂₁</th><th>r̂₂</th><th>γ=0.9 的预测回报</th><th>真实两步回报</th></tr></thead><tbody><tr><td>直行</td><td>+2</td><td>−10</td><td>−7.0</td><td>−7.0</td></tr><tr><td>绕行</td><td>0</td><td>+2</td><td>1.8</td><td>1.8</td></tr><tr><td>模型漏掉坑</td><td>+2</td><td>+2</td><td>3.8（错误高估）</td><td>−7.0</td></tr></tbody></table></div><p>第三行揭示规划器只能优化预测回报。世界模型漏掉坑时，会把最危险路线排第一；规划越强，越会稳定利用这个误差。解决办法不是“搜索更多”，而是收集坑附近数据、表达不确定性、惩罚分布外轨迹并缩短开放环滚动。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>模型预测控制为什么只执行第一步<span class=\"dd-badge eng\">闭环</span></h2><p class=\"dd-lead\">既然已经规划出十步，为什么不一次全部执行？</p><p>模型预测控制每轮在模型内滚动 H 步，选择最佳序列，却只执行第一个动作；收到真实观察后更新状态并重新优化。它用频繁校正限制预测误差累积，也能响应其他主体和环境变化。代价是每一步都要重新规划，因此要在 horizon、候选数和实时延迟之间取舍。</p><p>检查点必须来自真实环境：执行器返回的位置、库存或测试结果，而不是模型续写的“现在已经到达”。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>误差为什么随滚动长度放大<span class=\"dd-badge math\">误差传播</span></h2><p class=\"dd-lead\">单步平均只错一点，为什么长规划仍会完全偏离？</p><p>若每步状态误差上界为 ε，动力学对状态的敏感度近似 L，则粗略误差递推为 <code>eₜ₊₁≤L·eₜ+ε</code>。L&lt;1 时误差可能受控；L≈1 时近似线性累积；L&gt;1 时可快速放大。更糟的是规划器选择的动作并非训练数据随机动作，而是专门寻找模型预测的高回报区域，误差分布会发生偏移。</p><div class=\"dd-note warn\"><b>不能只报随机验证集的一步 MSE。</b>　还要测规划策略诱导轨迹上的多步预测、奖励误差、校准和真实回报。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>状态混叠和不确定性<span class=\"dd-badge intuition\">失败边界</span></h2><p class=\"dd-lead\">两个画面看起来相同，却需要相反动作时，模型该怎么办？</p><p>若单帧看不出小车向左还是向右运动，编码成相同 z 就是状态混叠；同一状态/动作会对应两种未来，确定性均值预测可能得到现实中不存在的中间结果。可用历史递归、记忆、概率分布或粒子信念表示隐藏状态，并把认知不确定性传给规划器。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>不确定来源</th><th>例子</th><th>策略</th></tr></thead><tbody><tr><td>环境随机性</td><td>相同动作有随机滑移</td><td>预测分布，优化风险敏感回报</td></tr><tr><td>观测不充分</td><td>看不到速度/隐藏库存</td><td>整合历史或维护信念状态</td></tr><tr><td>数据不足</td><td>未见过坑边动作</td><td>模型集成、置信边界、回到真实探索</td></tr><tr><td>环境变化</td><td>规则或其他主体改变</td><td>漂移检测与在线校正</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>怎样发现模型利用<span class=\"dd-badge eng\">评测</span></h2><p class=\"dd-lead\">规划器在模型里获得超高回报，为什么真实环境反而变差？</p><p>这叫模型利用：策略找到模型漏洞，例如预测某个不现实动作会反复得分。比较模型预测回报与真实回放回报，差值称为 model exploitation gap；按动作新颖度和滚动长度切片。可限制策略偏离数据分布、对不确定状态施加惩罚、使用模型集成分歧、定期把候选放回真实环境验证并将反例加入训练。</p><p>真实环境评测必须隔离且限权，因为“为了验证模型”不能授权高风险动作无限试错。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与路线</span></h2><p class=\"dd-lead\">世界模型是面向决策的近似动力学，不是拥有常识的完整小世界。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>常见误解</th><th>更准确的理解</th></tr></thead><tbody><tr><td>视频越逼真，世界模型越准确</td><td>决策关键动力学、奖励和终止可错，即使像素合理</td></tr><tr><td>单步误差低即可长程规划</td><td>误差会累积，规划器还会主动走向模型漏洞</td></tr><tr><td>想象轨迹等于环境观察</td><td>它只是预测，必须由真实执行闭环校正</td></tr><tr><td>规划越强越能弥补差模型</td><td>强规划往往更高效利用预测错误</td></tr><tr><td>一个向量状态总能概括当前世界</td><td>部分可观察环境需历史或概率信念</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>强化学习、状态/动作/奖励、神经网络</td></tr><tr><td><b>本页核心</b></td><td>潜在状态、转移/奖励模型、想象滚动、MPC 与不确定性</td></tr><tr><td>紧邻</td><td>智能体规划、模型式强化学习、状态空间模型、视频生成</td></tr><tr><td>工程延伸</td><td>测试时计算、可观测性、数据漂移、人在回路和安全约束</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>从真实轨迹学习状态与转移</li><li>在模型内滚动候选动作</li><li>按预测回报与风险评分</li><li>只执行近期动作</li><li>用真实观察校正状态</li><li>把模型利用反例回流训练</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>世界模型为何不等于视频生成器？</li><li>MPC 为什么只执行第一步？</li><li>什么是状态混叠？</li><li>强规划为何可能伤害真实表现？</li><li>应如何评估？</li><li>假设“世界模型：在内部状态中预测行动后的世界”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>规划需要动作条件下的动力学、奖励和终止正确，像素逼真不保证这些。</li><li>用新观察频繁校正，限制长滚动误差。</li><li>需要不同决策的真实状态被编码成同一内部状态。</li><li>它会主动寻找并利用模型预测漏洞。</li><li>测策略诱导轨迹的多步误差、校准、预测/真实回报差和最终环境回报。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1803.10122\" target=\"_blank\" rel=\"noopener\">World Models</a>：潜在世界模型与控制</li><li><a href=\"https://arxiv.org/abs/1912.01603\" target=\"_blank\" rel=\"noopener\">Dream to Control: Learning Behaviors by Latent Imagination</a>：Dreamer 潜在想象学习</li><li><a href=\"https://arxiv.org/abs/2301.04104\" target=\"_blank\" rel=\"noopener\">Mastering Diverse Domains through World Models</a>：DreamerV3</li><li><a href=\"https://arxiv.org/abs/1805.12114\" target=\"_blank\" rel=\"noopener\">PETS: Deep Reinforcement Learning in a Handful of Trials using Probabilistic Dynamics Models</a>：不确定动力学与模型预测控制</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
